"""Static, dependency-free Forge Studio 10-project showcase builder.
Run at workspace root: python tools/build_showcase.py. Never calls a network API.
"""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'site'
META = {
 'forgebench': ('#5B8CFF','#102852','⌘','Engineering evaluation','Software quality, typed APIs and reproducible tests','AI evaluation · TypeScript · Node.js'),
 'forgeml': ('#C889FF','#341C57','◌','Machine learning','Learn and measure preference ranking without invented scores','ML engineer · Python · numerical methods'),
 'forgemesh': ('#4DDBCB','#103D4B','⬡','Distributed services','Retry-safe messaging and concurrency resilience','Backend · Go · HTTP systems'),
 'forgecore': ('#FFC16F','#4B2818','◇','Systems planning','Deterministic resource scheduling and dependency graphs','Systems · C++20 · algorithms'),
 'forgeenterprise': ('#F1C269','#3A3045','▣','Enterprise workflow','Multi-stage approvals, roles and audit trails','Enterprise · Java · domain modeling'),
 'forgecloud': ('#7EBBFF','#103955','☁','Cloud readiness','Evidence-based release checks and rollback planning','DevOps · Python · infrastructure'),
 'forgemobile': ('#FF8BA7','#4E233C','▯','Mobile foundations','Offline mutation queue and conflict-safe synchronization','Mobile · Kotlin · offline-first'),
 'forgecommerce': ('#72E59D','#184737','▤','Commerce backend','Inventory reservations and concurrency safety','Backend · PHP · transactions'),
 'forgeconnect': ('#ABA5FF','#26265B','⇄','Integration engineering','Signed events, subscribers and retry-aware delivery','Integration · Ruby · webhooks'),
 'forgedatalab': ('#E6E878','#404421','▥','Data science','SQL telemetry aggregation and repeatable reporting','Data · Python · SQLite'),
}
SHAPES = {
 'forgebench': '<path d="M22 17 10 32l12 15M42 17l12 15-12 15M37 13 27 51"/>',
 'forgeml': '<circle cx="15" cy="18" r="5"/><circle cx="48" cy="18" r="5"/><circle cx="32" cy="46" r="6"/><path d="m19 21 10 19m15-19L35 40M21 18h22"/>',
 'forgemesh': '<path d="M32 7 54 19v26L32 57 10 45V19Z"/><path d="M32 7v50M10 19l44 26M54 19 10 45"/>',
 'forgecore': '<rect x="14" y="14" width="36" height="36" rx="8"/><path d="M23 7v7m18-7v7M23 50v7m18-7v7M7 23h7M7 41h7m36-18h7m-7 18h7M25 32h14m-7-7v14"/>',
 'forgeenterprise': '<path d="M12 54V23l20-14 20 14v31ZM19 54V30h26v24M26 35h12M26 43h12M26 54V16"/>',
 'forgecloud': '<path d="M18 44h30a12 12 0 0 0 0-24h-3a14 14 0 0 0-27 4 10 10 0 0 0 0 20Zm14-12v17m-8-7 8 8 8-8"/>',
 'forgemobile': '<rect x="20" y="7" width="24" height="50" rx="7"/><path d="M28 14h8M28 48h8M27 36l4 4 8-10"/>',
 'forgecommerce': '<path d="M16 20h32l4 32H12l4-32ZM24 23v-9a8 8 0 0 1 16 0v9M25 38l5 5 11-13"/>',
 'forgeconnect': '<path d="M8 22h33m-7-8 8 8-8 8M56 42H23m7-8-8 8 8 8M17 17l-7 5 7 5m30 10 7 5-7 5"/>',
 'forgedatalab': '<path d="M14 51V36h9v15m5 0V25h9v26m5 0V14h9v37M11 54h45"/>',
}
CSS = r'''@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#eff5fb;--muted:#a4b1c6;--panel:#141e2b;--panel2:#192635;--line:#324055;--bg:#09121f;--accent:#84d8ff;font-family:'DM Sans',system-ui,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:radial-gradient(ellipse 70% 45% at 80% -12%,#26435f80,transparent 70%),radial-gradient(ellipse 45% 26% at 0% 17%,#30244a55,transparent),var(--bg);color:var(--ink)}a{color:inherit;text-decoration:none}button,input{font:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #ffe5a2;outline-offset:4px}.wrap{width:min(1200px,calc(100% - 44px));margin:0 auto}.top{display:flex;align-items:center;justify-content:space-between;padding:29px 0 20px}.logo{display:flex;gap:12px;align-items:center;font-family:'Space Grotesk',sans-serif;font-size:18px;font-weight:700;letter-spacing:-.7px}.logo-symbol{width:34px;height:34px;border-radius:11px;background:linear-gradient(140deg,#8effd7,#72c5ff);color:#09131f;display:grid;place-items:center;font-size:23px;font-weight:900}.nav{display:flex;gap:23px;align-items:center;color:var(--muted);font-size:13px;font-weight:700}.nav a:hover{color:white}.label{font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:800;color:#85e6da}.hero{display:grid;grid-template-columns:1.2fr .8fr;align-items:end;gap:45px;padding:76px 0 74px;position:relative}.hero h1{font-family:'Space Grotesk',sans-serif;font-size:clamp(48px,7vw,89px);letter-spacing:-.075em;line-height:1.05;margin:19px 0 19px;font-weight:700}.hero h1 em{font-style:normal;color:#8dddc7}.hero p{max-width:650px;font-size:17px;line-height:1.73;color:#b4c3d2}.hero-side{border:1px solid #4a607650;border-radius:24px;padding:25px;background:linear-gradient(140deg,#1b2d3dcc,#0e1929dc);backdrop-filter:blur(8px)}.hero-number{font-size:64px;letter-spacing:-.06em;line-height:1;font-family:'Space Grotesk',sans-serif;font-weight:700}.hero-qual{color:#b4c3d2;font-size:12px;line-height:1.8;margin:10px 0}.minicount{display:grid;grid-template-columns:1fr 1fr;gap:15px;padding-top:22px;margin-top:23px;border-top:1px solid #3a5063}.minicount b{font-size:25px}.minicount span{display:block;color:var(--muted);font-size:12px;margin-top:5px}.strip{border-block:1px solid #40526b55;background:#0b172599;padding:17px 0}.strip-inner{display:flex;flex-wrap:wrap;gap:15px 30px;justify-content:space-between;color:#bfd0e0;font-size:12px;font-weight:700}.section-title{display:flex;justify-content:space-between;align-items:end;gap:15px;margin-top:70px}.section-title h2,.detail h1{font:700 clamp(30px,4.5vw,50px)/1.13 'Space Grotesk',sans-serif;letter-spacing:-.05em;margin:12px 0}.section-title p{color:var(--muted);max-width:450px;line-height:1.7;font-size:13px}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:24px 0 25px}.search{border:1px solid var(--line);border-radius:11px;background:#122030;color:var(--ink);min-width:min(310px,100%);padding:13px 17px}.filter{border:1px solid var(--line);border-radius:25px;background:transparent;color:#b5c6d5;padding:11px 14px;font-size:12px;cursor:pointer}.filter[aria-pressed=true]{color:#101e2d;background:#a2e9db;border-color:#a2e9db;font-weight:800}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding-bottom:45px}.card{position:relative;border:1px solid #344459;background:linear-gradient(145deg,#1d2a37,#111b29);border-radius:20px;padding:23px;min-height:284px;display:flex;flex-direction:column;overflow:hidden;transition:transform .2s,border-color .2s}.card:hover{transform:translateY(-4px);border-color:var(--tone)}.card:before{content:'';position:absolute;inset:0 0 auto;height:3px;background:var(--tone)}.cardhead{display:flex;justify-content:space-between;align-items:center}.symbol{width:57px;height:57px;border-radius:16px;border:1px solid color-mix(in srgb,var(--tone) 40%,transparent);background:color-mix(in srgb,var(--tone) 12%,#141b27);padding:12px}.symbol svg{width:100%;height:100%;fill:none;stroke:var(--tone);stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.index{font:700 13px 'Space Grotesk',sans-serif;color:#7b91a5}.card h3{font:700 24px 'Space Grotesk',sans-serif;letter-spacing:-.04em;margin:23px 0 5px}.category{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--tone);font-weight:800}.card p{color:#adbdca;line-height:1.55;font-size:13px;margin:13px 0 24px;flex:1}.tags{display:flex;flex-wrap:wrap;gap:6px}.tag{border-radius:5px;background:#2b3a4b;color:#cad7e2;padding:5px 8px;font-size:11px}.cardfoot{margin-top:19px;display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#91abbb}.cardfoot span:last-child{color:var(--tone);font-weight:800}.aside{display:grid;grid-template-columns:1fr 1fr;gap:30px;border-top:1px solid var(--line);margin-top:32px;padding:50px 0}.aside h2{font:700 28px 'Space Grotesk';letter-spacing:-.04em}.aside p{line-height:1.7;color:var(--muted);font-size:14px}.detail{padding:78px 0 30px}.detail-hero{padding:40px;border-radius:24px;border:1px solid color-mix(in srgb,var(--tone) 42%,#2c4358);background:radial-gradient(ellipse at top right,color-mix(in srgb,var(--tone) 17%,transparent),transparent 60%),#142131}.detail-title{display:flex;gap:20px;align-items:center}.detail h1{margin-bottom:7px}.detail h2{font:700 25px 'Space Grotesk'}.detail p{line-height:1.8;color:#b7c6d5}.detail .large{font-size:18px}.back{color:#9cdce4;font-size:13px;font-weight:700}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:26px 0}.detail-panel{background:#111e2d;border:1px solid #304358;border-radius:17px;padding:27px}.status{font-size:12px;color:#9adcc5;font-weight:700}.footer{border-top:1px solid var(--line);padding:27px 0 45px;display:flex;justify-content:space-between;gap:20px;color:#8fa5b8;font-size:12px}.hidden{display:none!important}@media(max-width:860px){.hero{grid-template-columns:1fr;padding:50px 0}.cards{grid-template-columns:repeat(2,1fr)}.nav{gap:12px}.aside,.detail-grid{grid-template-columns:1fr}}@media(max-width:600px){.cards{grid-template-columns:1fr}.wrap{width:min(100% - 30px,1200px)}.hero h1{font-size:51px}.hero-side{display:none}.section-title{display:block}.nav{font-size:12px}.nav .secondary{display:none}.footer{flex-direction:column}.detail-hero{padding:23px}.detail-title{align-items:flex-start}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
'''
JS = r'''const cards=[...document.querySelectorAll('[data-card]')];const search=document.querySelector('#search');const buttons=[...document.querySelectorAll('[data-filter]')];let current='All';function update(){const q=(search?.value||'').trim().toLowerCase();let found=0;for(const card of cards){const ok=(current==='All'||card.dataset.fields.toLowerCase().split(/[^a-z0-9#+.]+/).includes(current.toLowerCase()))&&(!q||card.textContent.toLowerCase().includes(q));card.classList.toggle('hidden',!ok);if(ok)found++;}const counter=document.querySelector('#found');if(counter)counter.textContent=found+(found===1?' project shown':' projects shown');}for(const b of buttons){b.addEventListener('click',()=>{current=b.dataset.filter;for(const other of buttons)other.setAttribute('aria-pressed',String(other===b));update();});}search?.addEventListener('input',update);update();'''

def esc(s): return html.escape(str(s), quote=True)
def icon(id):
    color,_,_,_,_,_ = META[id]
    return f'<svg viewBox="0 0 64 64" aria-hidden="true">{SHAPES[id]}</svg>'
def svg_file(id):
    color = META[id][0]
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#101b2b"/><g fill="none" stroke="{color}" stroke-width="3" stroke-linejoin="round" stroke-linecap="round">{SHAPES[id]}</g></svg>'
def header(prefix=''):
    return f'''<header class="top wrap"><a class="logo" href="{prefix}index.html" aria-label="Forge Studio engineering lab home"><span class="logo-symbol">F</span><span>Forge Studio <span style="color:#8aa9ba;font-size:12px;font-weight:500">/ ENGINEERING LAB</span></span></a><nav class="nav"><a href="{prefix}index.html#projects">Projects</a><a class="secondary" href="{prefix}index.html#method">Evidence</a><a href="https://github.com/ajkivela369-coder" rel="noopener noreferrer">GitHub</a></nav></header>'''
def footer(): return '<footer class="footer wrap"><span>Forge Studio · Research. Build. Create.</span><span>Local engineering prototypes · accurately documented scope</span></footer>'
def document(title,desc,body,prefix='',style=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#0a1521"><title>{esc(title)}</title><link rel="stylesheet" href="{prefix}assets/style.css">{style}</head><body>{header(prefix)}{body}{footer()}<script src="{prefix}assets/filter.js" defer></script></body></html>'''
def main():
    manifest=json.loads((ROOT/'portfolio-manifest.json').read_text('utf-8'))
    projects=manifest['projects']
    assert len(projects)==10 and set(x['id'] for x in projects)==set(META)
    (SITE/'assets'/'icons').mkdir(parents=True,exist_ok=True)
    (SITE/'assets'/'style.css').write_text(CSS,'utf-8')
    (SITE/'assets'/'filter.js').write_text(JS,'utf-8')
    cards=[]
    for i,pr in enumerate(projects,1):
        id=pr['id']; color, dark, symbol, category, summary, focus=META[id]
        (SITE/'assets'/'icons'/f'{id}.svg').write_text(svg_file(id),'utf-8')
        languages=pr.get('implemented_languages',[])
        fields=(category+' '+focus+' '+' '.join(languages)).lower()
        tags=''.join(f'<span class="tag">{esc(lang)}</span>' for lang in languages[:4])
        cards.append(f'''<a class="card" data-card data-fields="{esc(fields)}" style="--tone:{color}" href="apps/{id}/index.html" aria-label="Explore {esc(pr['title'])}"><div class="cardhead"><div class="symbol">{icon(id)}</div><span class="index">{i:02d} / 10</span></div><h3>{esc(pr['title'])}</h3><div class="category">{esc(category)}</div><p>{esc(summary)}</p><div class="tags">{tags}</div><div class="cardfoot"><span>Tested prototype</span><span>Explore ↗</span></div></a>''')
        detail=f'''<main class="wrap detail" style="--tone:{color}"><a class="back" href="../../index.html#projects">← All ten projects</a><section class="detail-hero" style="margin-top:25px"><div class="detail-title"><div class="symbol">{icon(id)}</div><div><div class="label" style="color:{color}">{esc(category)}</div><h1>{esc(pr['title'])}</h1></div></div><p class="large">{esc(summary)}.</p><p>{esc(focus)}</p><span class="status">● Verified prototype core · not a publicly deployed full application</span></section><section class="detail-grid"><article class="detail-panel"><h2>Implemented skills</h2><div class="tags">{''.join(f'<span class="tag">{esc(t)}</span>' for t in languages+pr.get('implemented_stacks',[]))}</div><p>These languages and tools appear in the working source, rather than a wish list.</p></article><article class="detail-panel"><h2>Testing &amp; limits</h2><p>{esc(pr.get('verification','See the project README for verification details.'))}</p></article><article class="detail-panel"><h2>Next technologies</h2><div class="tags">{''.join(f'<span class="tag">{esc(t)}</span>' for t in pr.get('target_stacks',[]) if t not in pr.get('implemented_stacks',[]))}</div><p>Roadmap candidates only; not claimed as implemented or production-ready.</p></article><article class="detail-panel"><h2>Source &amp; documentation</h2><p>Source is in the Forge Studio ten-project workspace under <code>{esc(pr['location'])}/</code>. See that project's README for reproducible checks. Remote GitHub links will be added only after publication is verified.</p><p><a class="back" href="../../index.html">← Return to portfolio</a></p></article></section></main>'''
        path=SITE/'apps'/id;path.mkdir(parents=True,exist_ok=True)
        (path/'index.html').write_text(document(pr['title']+' — Forge Studio',summary,detail,prefix='../../',style=f'<link rel="icon" type="image/svg+xml" href="../../assets/icons/{id}.svg">'),'utf-8')
    count=manifest.get('top_level_passing_tests',188)
    hero=f'''<main><section class="hero wrap"><div><div class="label">Ten domains. One engineering portfolio.</div><h1>Built to <em>work.</em><br>Built to prove it.</h1><p>Ten distinct software projects covering coding evaluation, AI, backend systems, infrastructure, commerce, enterprise, mobile foundations and data science. Working prototypes with runnable checks, clear boundaries and room to grow.</p></div><div class="hero-side"><div class="label">Current engineering evidence</div><div class="hero-number">10<span style="color:#81e6c9">/10</span></div><p class="hero-qual">Tested prototype cores. These are not ten independently deployed production web apps.</p><div class="minicount"><div><b>{count}</b><span>Top-level passing checks across verified environments</span></div><div><b>9+</b><span>Core source languages represented</span></div></div></div></section><div class="strip"><div class="wrap strip-inner"><span>TypeScript + JavaScript</span><span>Python + SQL</span><span>Java + Kotlin</span><span>Go + C++</span><span>PHP + Ruby</span></div></div><section class="wrap" id="projects"><div class="section-title"><div><div class="label">Work samples / 01–10</div><h2>Explore the projects.</h2></div><p>Each project has its own technical focus, visual identity and evidence of what is implemented today.</p></div><div class="toolbar"><input id="search" class="search" type="search" placeholder="Find a language, skill or project…" aria-label="Search projects"><button type="button" class="filter" data-filter="All" aria-pressed="true">All</button><button type="button" class="filter" data-filter="Python" aria-pressed="false">Python</button><button type="button" class="filter" data-filter="Backend" aria-pressed="false">Backend</button><button type="button" class="filter" data-filter="Java" aria-pressed="false">Java</button><button type="button" class="filter" data-filter="Mobile" aria-pressed="false">Mobile</button><span id="found" style="color:#91a7b7;font-size:12px" role="status"></span></div><div class="cards">{''.join(cards)}</div></section><section class="wrap aside" id="method"><div><div class="label">Verification first</div><h2>Evidence over buzzwords.</h2><p>Each project's page distinguishes implemented languages from aspirational frameworks. The tests use synthetic fixtures and document local-versus-Linux environments.</p></div><div><div class="label">Career readiness</div><h2>Job-relevant engineering.</h2><p>Projects span APIs, state machines, SQL, testing, concurrent services, security primitives, cloud readiness and offline-first sync. Production hardening and polished interactive apps remain separate milestones.</p></div></section></main>'''
    (SITE/'index.html').write_text(document('Ten Engineering Projects — Forge Studio','Ten tested engineering prototypes with honest scope, hiring-relevant technologies and distinct visual identities.',hero),'utf-8')
    print('Generated 10 app detail pages, 10 SVG icons, index and assets at',SITE)
if __name__ == '__main__': main()
